 14 | 
 15 | @theme {
 16 |   --color-*: initial;
 17 | 
 18 |   /* PRIMARY STRATEGY: OCEANIC */
 19 |   --color-oceanic-dark: #005B6D;      /* Primary brand, high contrast */
 20 |   --color-oceanic-accent: #007489;    /* Interactive elements */
 21 |   --color-oceanic-secondary: #218993; /* Secondary actions */
 22 |   --color-oceanic-subtle: #7A9FA7;    /* Muted text, borders */
 23 | 
 24 |   /* VERIFIED ACCENTS */
 25 |   --color-warm-gold: #D4C19C;         /* Premium highlights */
 26 |   --color-slate-teal: #4A6163;        /* Neutral complement */
 27 |   --color-liberty-blue: #2E4A62;      /* Federal aesthetic */
 28 |   --color-heritage-red: #8B3E2F;      /* Alert, emphasis */
 29 |   --color-frost-mint: #E2F0E9;        /* Success, subtle bg */
 30 | 
 31 |   /* UI FOUNDATION */
 32 |   --color-ink: #0F151B;               /* Primary text */
 33 |   --color-canvas: #FAF9F6;            /* Page background */
 34 |   --color-soft-smoke: #F0F0F0;        /* Subtle dividers */
 35 | 
 36 |   /* AIRY SPACING (FEDERAL SCALE) */
 37 |   --spacing-airy-sm: 2rem;            /* 32px - Compact sections */
 38 |   --spacing-airy-md: 4rem;            /* 64px - Standard vertical rhythm */
 39 |   --spacing-airy-lg: 6rem;            /* 96px - Generous breathing room */
 40 |   --spacing-airy-xl: 10rem;           /* 160px - Statement sections */
 41 |   --spacing-airy-2xl: 14rem;          /* 224px - Hero padding */
 42 |   --spacing-airy-massive: 20rem;      /* 320px - Ultra-premium spacing */
 43 | 
 44 |   /* TYPOGRAPHY SCALE (STRATEGY-2 INSPIRED) */
 45 |   --font-size-xs: 0.75rem;            /* 12px - Metadata */
 46 |   --font-size-sm: 0.9rem;             /* 14px - Label */
 47 |   --font-size-base: 1rem;             /* 16px - Body text */
 48 |   --font-size-lg: 1.125rem;           /* 18px - Lead paragraph */
 49 |   --font-size-xl: 1.25rem;            /* 20px - Subheading */
 50 |   --font-size-2xl: 1.5rem;            /* 24px - Section title */
 51 |   --font-size-3xl: 1.8rem;            /* 28px - Display text clamp min */
 52 |   --font-size-4xl: 2.5rem;            /* 40px - Hero title clamp min */
 53 |   --font-size-5xl: 3.2rem;            /* 51px - Display text max */
 54 |   --font-size-6xl: 5.5rem;            /* 88px - Hero title max */
 55 | 
 56 |   /* FONT FAMILIES */
 57 |   --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
 58 |   --font-serif: 'Georgia', 'Times New Roman', serif;
 59 |   --font-mono: 'SF Mono', 'Consolas', monospace;
 60 | }
 61 | 
 62 | /* Base resets & utilities */
 63 | body {
 64 |   font-family: var(--font-sans);
 65 |   color: var(--color-ink);
 66 |   background-color: var(--color-canvas);
 67 |   line-height: 1.5;
 68 |   -webkit-font-smoothing: antialiased;
 69 |   -moz-osx-font-smoothing: grayscale;
 70 |   overscroll-behavior: none;
 71 | }
 72 | 
 73 | @layer utilities {
 74 |   .section-padding {
 75 |     padding: 12rem 2rem;
 76 |   }
 77 |   
 78 |   .text-label {
 79 |     font-size: var(--font-size-sm);
 80 |     font-weight: 600;
 81 |     letter-spacing: 0.3em;
 82 |     text-transform: uppercase;
 83 |   }
 84 |   
 85 |   .display-text {
 86 |     font-size: clamp(1.8rem, 4.5vw, 3.2rem);
 87 |     line-height: 1.25;
 88 |     font-weight: 300;
 89 |     letter-spacing: -0.01em;
 90 |   }
 91 |   
 92 |   .hero-title {
 93 |     font-size: clamp(2.5rem, 9vw, 5.5rem);
 94 |     font-weight: 300;
 95 |     line-height: 1;
 96 |     letter-spacing: -0.04em;
 97 |   }
 98 | }
 99 | 
100 | /* Fluid.Glass / Brutalist Components */
101 | .tech-border {
102 |   border: 1px solid rgba(15, 21, 27, 0.1); /* Based on ink */
103 | }
104 | .dark .tech-border,
105 | .dark.tech-border {
106 |   border: 1px solid rgba(255, 255, 255, 0.15);
107 | }
108 | 
109 | .mono {
110 |   font-family: var(--font-mono);
111 | }
